// 優惠/方案截止日倒數（每秒即時遞減）
function pad2(n) { return String(n).padStart(2, '0'); }
function updateDeadlineCountdowns() {
  document.querySelectorAll('.deadline-countdown').forEach(el => {
    const target = new Date(el.dataset.deadline).getTime();
    const diff = target - Date.now();
    if (diff <= 0) {
      el.textContent = '⛔ 已截止';
      el.classList.add('expired');
      return;
    }
    const d = Math.floor(diff / 86400000);
    const h = Math.floor((diff % 86400000) / 3600000);
    const m = Math.floor((diff % 3600000) / 60000);
    const s = Math.floor((diff % 60000) / 1000);
    const clock = `${pad2(h)}:${pad2(m)}:${pad2(s)}`;
    el.innerHTML = d > 0
      ? `倒數 ${d} 天 <span class="cd-clock">${clock}</span>`
      : `倒數 <span class="cd-clock">${clock}</span>`;
  });
}
updateDeadlineCountdowns();
setInterval(updateDeadlineCountdowns, 1000);

